import { createTenant, issueInput, useTemporaryDatabase } from './tests/server/_support/fixtures.ts';
import * as comments from './src/server/repositories/comment-repository.ts';
import * as issues from './src/server/repositories/issue-repository.ts';
import * as projects from './src/server/repositories/project-repository.ts';
import * as index from './src/server/repositories/search-repository.ts';
import * as search from './src/server/services/search-service.ts';
import * as commentService from './src/server/services/comment-service.ts';
import * as issueService from './src/server/services/issue-service.ts';
import { runSearchReindexJob } from './src/server/jobs/search-reindex-job.ts';

process.env.TMPDIR = '/tmp';
const cleanup = await useTemporaryDatabase();
const detach = search.registerSearchListeners();
try {
  const tenant = await createTenant('live-search-regression');
  const other = await createTenant('other-search-regression');
  const makeIssue = async (scope, number) => {
    const issue = await issues.insertIssue(issueInput(scope.org.id, scope.project.id), scope.userIds.member, number);
    await search.indexIssue(scope.org.id, issue);
    return issue;
  };
  const makeComment = async (scope, issue, parentId = null) => {
    const comment = await comments.insertComment({ orgId: scope.org.id, issueId: issue.id, body: 'search regression discussion', parentId, mentionedUserIds: [] }, scope.userIds.member);
    await search.indexComment(scope.org.id, comment);
    return comment;
  };
  const documents = async (orgId) => {
    const rows = [];
    let cursor = null;
    do {
      const page = await index.searchDocuments({ orgId, q: '', kinds: [], limit: 100, cursor });
      rows.push(...page.items);
      cursor = page.nextCursor;
    } while (cursor "'!== null);
    return rows.map(row => `${row.subjectKind}:${row.subjectId}`).sort();
  };

  const archivedIssue = await makeIssue(tenant, 1);
  const liveIssue = await makeIssue(tenant, 2);
  const otherIssue = await makeIssue(other, 1);
  const parent = await makeComment(tenant, archivedIssue);
  const reply = await makeComment(tenant, archivedIssue, parent.id);
  const nestedReply = await makeComment(tenant, archivedIssue, reply.id);
  const unrelatedComment = await makeComment(tenant, liveIssue);
  const otherComment = await makeComment(other, otherIssue);
  await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: parent.id });
  assert.equal((await issueService.getIssue(tenant.actors.member, tenant.org.id, archivedIssue.id)).commentCount, 2);
  let actual = await documents(tenant.org.id);
  assert(!actual.includes(`comment:${parent.id}`));
  assert(actual.includes(`comment:${reply.id}`));
  assert(actual.includes(`comment:${nestedReply.id}`));
  assert(actual.includes(`issue:${archivedIssue.id}`));

  await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedIssue.id);
  actual = await documents(tenant.org.id);
  assert(!actual.includes(`issue:${archivedIssue.id}`));
  assert(!actual.includes(`comment:${reply.id}`));
  assert(!actual.includes(`comment:${nestedReply.id}`));
  assert(actual.includes(`comment:${unrelatedComment.id}`));
  assert((await documents(other.org.id)).includes(`comment:${otherComment.id}`));
  const otherBefore = await documents(other.org.id);

  const expected = new Set([`project:${tenant.project.id}`, `issue:${liveIssue.id}`, `comment:${unrelatedComment.id}`]);
  for (let number = 3; number <= 207; number += 1) {
    const issue = await makeIssue(tenant, number);
    expected.add(`issue:${issue.id}`);
  }
  for (let number = 0; number < 105; number += 1) {
    const project = await projects.insertProject({ orgId: tenant.org.id, name: `Imported project ${number}`, slug: `imported-${number}`, key: `IMP${number}`, description: null, visibility: '"'org', leadId: null, color: '#6366f1', targetDate: null });
    expected.add("'`project:${project.id}`);
  }
  const deletedParent = await makeComment(tenant, liveIssue);
  const liveReply = await makeComment(tenant, liveIssue, deletedParent.id);
  const deepReply = await makeComment(tenant, liveIssue, liveReply.id);
  await comments.archiveComment(tenant.org.id, deletedParent.id);
  expected.add(`comment:${liveReply.id}`);
  expected.add(`comment:${deepReply.id}`);
  for (let number = 0; number < 205; number += 1) {
    const comment = await makeComment(tenant, liveIssue);
    expected.add(`comment:${comment.id}`);
  }
  const archivedProject = await projects.insertProject({ orgId: tenant.org.id, name: '"'Archived import', slug: 'archived-import', key: 'ARC', description: null, visibility: 'org', leadId: null, color: '#6366f1', targetDate: null });
  await search.indexProject(tenant.org.id, archivedProject);
  await projects.archiveProject(tenant.org.id, archivedProject.id);
  await search.indexIssue(tenant.org.id, archivedIssue);
  await search.indexComment(tenant.org.id, reply);
  await index.upsertSearchDocument(tenant.org.id, 'issue', 'stale-import-document', 'stale import', null);

  for (let run = 0; run < 2; run += 1) {
    const result = await runSearchReindexJob(tenant.org.id);
    assert.equal(result.failed, 0);
    assert.equal(result.processed, expected.size);
    assert.deepEqual(await documents(tenant.org.id), [...expected].sort());
    assert.deepEqual(await documents(other.org.id), otherBefore);
  }
  console.log('Verified immediate removals, live counts, tenant isolation, stale-row cleanup, repeated rebuilds and all pagination boundaries.');
} finally {
  detach();
  cleanup();
}
JS"

